import pandas as pd


def run(inputs: dict) -> dict:
    target = inputs["target_snapshot"]
    cdc = inputs["cdc_events"]
    wm = inputs["watermark"]

    # Determine watermark high_ts (events with ts <= high_ts are already applied)
    if wm is not None and len(wm) > 0:
        high_ts = wm["high_ts"].iloc[0]
    else:
        high_ts = pd.NaT

    # Filter events strictly after watermark
    if pd.isna(high_ts):
        events = cdc.copy()
    else:
        events = cdc[cdc["event_ts"] > high_ts].copy()

    # Sort events by (event_ts, event_seq) ascending - stable sort for determinism
    events = events.sort_values(["event_ts", "event_seq"], kind="mergesort")

    # Initialize per-item state from the target_snapshot
    state = {}
    for _, row in target.iterrows():
        item = row["item_id"]
        state[item] = {
            "exists": True,
            "qty": float(row["qty_on_hand"]) if pd.notna(row["qty_on_hand"]) else None,
            "last_ts": row["last_event_ts"],
        }

    # Apply events sequentially per item
    for _, row in events.iterrows():
        item = row["item_id"]
        op = row["op"]
        qty = row["qty"]
        ts = row["event_ts"]

        if item not in state:
            state[item] = {"exists": False, "qty": None, "last_ts": None}

        s = state[item]

        if op == "R":
            if not s["exists"]:
                s["qty"] = 0.0 + (qty if pd.notna(qty) else 0.0)
            else:
                base = s["qty"] if s["qty"] is not None else 0.0
                s["qty"] = base + (qty if pd.notna(qty) else 0.0)
            s["exists"] = True
            s["last_ts"] = ts
        elif op == "A":
            s["qty"] = float(qty) if pd.notna(qty) else None
            s["exists"] = True
            s["last_ts"] = ts
        elif op == "D":
            s["exists"] = False
            s["qty"] = None
            s["last_ts"] = None
        else:
            # Unknown op codes are ignored (no-op) to stay defensive.
            pass

    # Build output rows only for items currently present
    out_rows = []
    for item, s in state.items():
        if s["exists"]:
            out_rows.append(
                {
                    "item_id": item,
                    "qty_on_hand": s["qty"],
                    "last_event_ts": s["last_ts"],
                }
            )

    new_snapshot = pd.DataFrame(
        out_rows, columns=["item_id", "qty_on_hand", "last_event_ts"]
    )

    if len(new_snapshot) > 0:
        new_snapshot["item_id"] = new_snapshot["item_id"].astype("int64")
        new_snapshot["qty_on_hand"] = new_snapshot["qty_on_hand"].astype("float64")
        new_snapshot["last_event_ts"] = pd.to_datetime(new_snapshot["last_event_ts"])
    else:
        new_snapshot = pd.DataFrame(
            {
                "item_id": pd.Series(dtype="int64"),
                "qty_on_hand": pd.Series(dtype="float64"),
                "last_event_ts": pd.Series(dtype="datetime64[us]"),
            }
        )

    return {"new_snapshot": new_snapshot}
